      "to": "'/api/bookings'",
      "label": "the list calls the wrong path"
    },
    {
      "file": "web/AdminBookings.jsx",
      "from": "state.bookings.length === 0",
      "to": "state.bookings.length < 0",
      "label": "an empty list shows an empty table"
    },
    {
      "file": "web/AdminBookings.jsx",
      "from": "if (res.status === 403)",
      "to": "if (res.status === 401)",
      "label": "403 shown as a generic failure"
    },
    {
      "file": "web/AdminBookings.jsx",
      "from": "onClick={load}",
      "to": "onClick={undefined}",
      "label": "Try again does nothing"
    },
    {
      "file": "web/BookingForm.jsx",
      "from": "'Cannot reach the server. Check your connection.'",
      "to": "'Something went wrong. Try again.'",
      "label": "a lost connection looks like a server error"
